                    window.krpano.get('hotspot').getArray().map((val, inx) => {
                        if (val.name.indexOf('_hotspot_') != -1) {
                            names.push(val.name)
                        }
                    })
                    names.map((val) => {
                        window.krpano.call('removehotspot(' + val + ')')
                    })

